		case "reset": self = .reset(try Reset(from: decoder))
		default: self = .unknown(tag)
		}
	}

	func encode(to encoder: any Encoder) throws {
		switch self {
		case let .threadChanged(value): try value.encode(to: encoder)
		case let .conversationThreadChanged(value): try value.encode(to: encoder)
